css:
.print-format {
  margin-top: 25mm;
  margin-bottom: 13mm;
  header-spacing: 3;
  margin-left: 11mm;
  margin-right: 11mm;
  padding: 0 !important;
  min-height: 0 !important;
  font-size: 8.5pt;
}

html body .print-format, body .print-format { margin: 0 !important; padding: 0 !important; min-height: 0 !important; }

html body, body[onload] { padding: 0 !important; margin: 0 !important; }

.print-format .afm,
.print-format .afm td,
.print-format .afm th,
.print-format .afm div,
.print-format .afm span {
  font-family: "Noto Sans Arabic", "Noto Sans", "DejaVu Sans", sans-serif !important;
}
.print-format .afm .en, .print-format .afm .num, .print-format .afm .ltr, .print-format .afm .num span {
  font-family: "Noto Sans", "DejaVu Sans", sans-serif !important;
}
.print-format .afm {
  color: #171717;
  font-size: 8.5pt;
  line-height: 14px;
  font-weight: normal;
  direction: rtl;
  text-align: right;
  -webkit-print-color-adjust: exact;
}
.afm * { box-sizing: border-box; }
.afm p { margin: 0; }
.afm b, .afm strong { font-weight: bold; }


.afm .ar { font-size: 7pt; line-height: 12px; font-weight: normal; color: #5f5f5f; }
.afm .en { font-size: 6pt; line-height: 10px; font-weight: normal; color: #5f5f5f; direction: ltr; unicode-bidi: embed; }
.afm .pair { display: table; width: 100%; line-height: 12px; }
.afm .pair .ar { display: table-cell; text-align: right; white-space: nowrap; vertical-align: baseline; }
.afm .pair .en { display: table-cell; text-align: left; white-space: nowrap; vertical-align: baseline; padding: 0 4px 0 0; }


.afm .num { white-space: nowrap; direction: ltr; unicode-bidi: embed; text-align: right; }
.afm .ctr { text-align: center !important; }
.afm .ltr { direction: ltr; unicode-bidi: embed; }


.afm table { width: 100%; border-collapse: collapse; table-layout: fixed; border-spacing: 0; }

.print-format .afm td, .print-format .afm th { padding: 1px 4px !important; vertical-align: top !important; word-wrap: break-word; }


.afm .head { margin: 0 0 8px 0; border-bottom: 1.2pt solid #00844e; }
.print-format .afm .head > tbody > tr > td { padding: 0 0 4px 0 !important; vertical-align: bottom !important; }
.afm .head .t-ar { font-size: 13pt; line-height: 20px; font-weight: bold; display: block; white-space: nowrap; }
.afm .head .t-en { font-size: 8.5pt; line-height: 14px; color: #5f5f5f; direction: ltr; unicode-bidi: embed; display: block; white-space: nowrap; }


.afm .kv { margin: 0 0 8px 0; }
.print-format .afm .kv td { border: 0.75pt solid #d0d0d0; }
.print-format .afm .head .kv { margin: 0; }
.print-format .afm .kv td.empty { border: 0; }
.afm .kv .v { display: block; font-size: 8.5pt; line-height: 14px; color: #171717; white-space: nowrap; }
.afm .kv .v.wrap { white-space: normal; }
.afm .kv .v.num { text-align: right; }
.afm .kv .v.b { font-weight: bold; }
.afm .kv td.plabel { border: 0; border-top: 1.2pt solid #00844e; vertical-align: middle !important; }
.afm .kv td.plabel .ar { font-weight: bold; color: #00844e; }


.afm .items { margin: 0 0 8px 0; }
.afm .items thead { display: table-header-group; }
.afm .items tfoot { display: table-footer-group; }
.afm .items tr { page-break-inside: avoid; }
.print-format .afm .items th {
  background: #f4f4f4;
  border-top: 1.2pt solid #00844e;
  border-bottom: 0.75pt solid #d0d0d0;
  text-align: right !important;
  font-weight: bold;
  white-space: nowrap;
  vertical-align: bottom !important;
}
.afm .items th .ar { font-weight: bold; color: #171717; display: block; white-space: nowrap; }
.afm .items th .en { display: block; white-space: nowrap; }
.print-format .afm .items td { border-bottom: 0.75pt solid #d0d0d0; font-size: 8.5pt; line-height: 14px; vertical-align: middle !important; }
.print-format .afm .items td.num { text-align: right !important; }
.afm .items .sub { color: #5f5f5f; font-size: 7pt; line-height: 12px; }


.afm .band { page-break-inside: avoid; margin: 0 0 8px 0; }
.print-format .afm .band > tbody > tr > td { padding: 0 !important; }
.afm .qr img { width: 96px; height: 96px; display: block; }
.print-format .afm .band td.words { padding: 0 8px !important; }
.afm .words .w { font-size: 8.5pt; line-height: 14px; margin: 0 0 8px 0; }
.print-format .afm .sign td { border-bottom: 0.75pt solid #5f5f5f; padding: 0 !important; height: 40px; }
.print-format .afm .sign td.gap { border: 0; }
.print-format .afm .tot td { border-bottom: 0.75pt solid #d0d0d0; vertical-align: middle !important; }
.afm .tot td.num { font-weight: bold; }
.afm .tot tr.grand td { background: #00844e; color: #ffffff; border-bottom: 0; font-weight: bold; }
.afm .tot tr.grand .ar, .afm .tot tr.grand .en { color: #ffffff; }
.afm .tot tr.grand .ar { font-weight: bold; }


.afm .note { font-size: 7pt; line-height: 12px; color: #171717; page-break-inside: avoid; overflow: hidden; }
.print-format .afm .note p, .print-format .afm .note .ql-editor { margin: 0 !important; padding: 0 !important; line-height: 12px !important; font-size: 7pt !important; }
.afm .note img { float: left; max-height: 80px; width: auto; margin: 0 0 0 8px; }
.afm .note .k { display: inline-block; padding: 0 0 0 4px; white-space: nowrap; }
.afm .note .k, .afm .note .k .en { color: #5f5f5f; font-size: 7pt; line-height: 12px; }


.afm-hdr .logo img { height: 48px; width: auto; display: block; }
.afm-hdr .n-ar { font-size: 13pt; line-height: 20px; font-weight: bold; display: block; color: #171717; white-space: nowrap; }
.afm-hdr .n-en { font-size: 8.5pt; line-height: 14px; color: #00844e; direction: ltr; unicode-bidi: embed; display: block; white-space: nowrap; }
.print-format .afm-hdr td { padding: 0 !important; vertical-align: middle !important; }
.afm-hdr .ids td { font-size: 8.5pt; line-height: 14px; white-space: nowrap; vertical-align: baseline !important; }
.afm-hdr .ids td.num { text-align: right !important; }
.afm-hdr .ids .k { font-size: 7pt; color: #5f5f5f; }
.afm-hdr .ids .k.ltr { font-size: 6pt; }
.afm-hdr .rule td { height: 8px; }
.afm-hdr .rule .thin { border-bottom: 0.75pt solid #00844e; }
.afm-hdr .rule .thick { border-bottom: 2.4pt solid #00844e; }


.print-format .afm-ftr td { border-top: 0.75pt solid #00844e; padding: 4px 0 0 0 !important; font-size: 7pt; line-height: 12px; color: #5f5f5f; vertical-align: top !important; }
.afm-ftr .ltr { white-space: nowrap; }
.afm-ftr .co { white-space: nowrap; }
.afm-ftr .ltr2 { direction: ltr; text-align: right; white-space: nowrap; padding: 0 4px 0 0; font-family: "Noto Sans", "DejaVu Sans", sans-serif; }
.afm-ftr .pg { white-space: nowrap; color: #171717; }


.afm.sam .en { font-size: 7pt; line-height: 12px; }
.afm.sam .ar { font-size: 7pt; line-height: 12px; }
.print-format .afm.sam td, .print-format .afm.sam th { border: 0.75pt solid #d0d0d0; vertical-align: middle !important; }
.afm.sam .lb-en { text-align: right; white-space: nowrap; }
.afm.sam .lb-en .en { direction: ltr; unicode-bidi: embed; }
.afm.sam .lb-ar { text-align: left; white-space: nowrap; }
.afm.sam .v { font-size: 8.5pt; line-height: 14px; color: #171717; white-space: nowrap; }
.afm.sam .v.wrap { white-space: normal; }
.afm.sam .v.b { font-weight: bold; }
.afm.sam .num { text-align: right; }
.afm.sam .v.num { text-align: center; }


.afm.sam .sam-title { margin: 0 0 8px 0; }
.print-format .afm.sam .sam-title th { background: #00844e; color: #ffffff; border: 0; padding: 1px 8px !important; vertical-align: middle !important; white-space: nowrap; }
.afm.sam .sam-title .t-en { text-align: right; font-size: 8.5pt; line-height: 20px; font-weight: bold; }
.afm.sam .sam-title .t-en .ltr { font-family: "Noto Sans", "DejaVu Sans", sans-serif !important; }
.afm.sam .sam-title .t-ar { text-align: left; font-size: 13pt; line-height: 20px; font-weight: bold; }


.afm.sam .sam-top { margin: 0 0 8px 0; }
.print-format .afm.sam .sam-top > tbody > tr > td { border: 0; padding: 0 !important; vertical-align: top !important; }
.print-format .afm.sam .sam-top td.qr { padding: 0 0 0 0 !important; text-align: left; }
.afm.sam .sam-top td.qr img { width: 96px; height: 96px; display: block; }
.afm.sam .sam-kv { width: 100%; }


.afm.sam .sam-parties { margin: 0 0 8px 0; }
.afm.sam .sam-party.hd .en, .afm.sam .sam-party.hd .ar { color: #00844e; font-weight: bold; }
.print-format .afm.sam .sam-party.hd td { border-top: 1.2pt solid #00844e; }
.afm.sam .sam-party td.v.wrap { vertical-align: top !important; }


.afm.sam .sam-items { margin: 0 0 8px 0; }
.afm.sam .sam-items thead { display: table-header-group; }
.afm.sam .sam-items tr { page-break-inside: avoid; }
.print-format .afm.sam .sam-items th { background: #f4f4f4; border-top: 1.2pt solid #00844e; text-align: right !important; vertical-align: bottom !important; white-space: nowrap; font-weight: normal; }
.print-format .afm.sam .sam-items th.ctr { text-align: center !important; }
.afm.sam .sam-items th .en, .afm.sam .sam-items th .ar { display: block; white-space: nowrap; }
.afm.sam .sam-items th .en { font-size: 6pt; line-height: 10px; color: #5f5f5f; }
.afm.sam .sam-items th .ar { font-weight: bold; color: #171717; }
.print-format .afm.sam .sam-items td { font-size: 8.5pt; line-height: 14px; }
.print-format .afm.sam .sam-items td.num { text-align: right !important; }


.afm.sam .sam-close, .afm.sam .sam-close tr { page-break-inside: avoid; }
.print-format .afm.sam .sam-close > tbody > tr > td { border: 0; padding: 0 !important; }
.print-format .afm.sam .sam-band td { background: #f4f4f4; border-top: 1.2pt solid #00844e; }
.afm.sam .sam-band .en, .afm.sam .sam-band .ar { color: #171717; font-weight: bold; }
.print-format .afm.sam .sam-tot td.num { font-size: 8.5pt; line-height: 14px; font-weight: bold; }
.print-format .afm.sam .sam-tot tr.grand td { background: #00844e; color: #ffffff; border-color: #00844e; }
.afm.sam .sam-tot tr.grand .en, .afm.sam .sam-tot tr.grand .ar { color: #ffffff; font-weight: bold; }
.print-format .afm.sam .sam-words td { font-size: 8.5pt; line-height: 14px; padding: 4px 4px !important; }
.print-format .afm.sam .sam-words td.blank { height: 40px; }

html:
{%- set _afm_co = frappe.db.get_value('Company', doc.company, ['company_name', 'company_name_in_arabic', 'tax_id', 'company_logo'], as_dict=1) or {} -%}
{%- set _afm_zbs = frappe.db.get_value('ZATCA Business Settings', {'company': doc.company}, 'name') if doc.company else none -%}
{%- set _afm_ns = namespace(cr='', street='', postal='') -%}
{%- if _afm_zbs -%}
  {%- set _afm_z = frappe.get_doc('ZATCA Business Settings', _afm_zbs) -%}
  {%- for r in _afm_z.other_ids -%}{%- if r.type_code == 'CRN' and r.value and not _afm_ns.cr -%}{%- set _afm_ns.cr = r.value -%}{%- endif -%}{%- endfor -%}
  {%- set _afm_ns.street = _afm_z.street or '' -%}{%- set _afm_ns.postal = _afm_z.postal_code or '' -%}
{%- endif -%}

{%- set afm = {
  'name_ar': _afm_co.company_name_in_arabic or _afm_co.company_name or doc.company,
  'name_en': 'AFMCO Ltd. for Support Services',
  'vat': _afm_co.tax_id or '',
  'cr': _afm_ns.cr,
  'logo': _afm_co.company_logo or '/files/afmco-logo-full-1200w.png',
  'addr': [_afm_ns.street, _afm_ns.postal] | select | join(' - '),
  'phone': '011 242 5473',
  'web': 'www.afmcoltd.com'
} -%}
<div id="header-html">
<div class="afm afm-hdr" dir="rtl" lang="ar">
  <table>
    <colgroup><col style="width:30mm"><col><col style="width:66mm"></colgroup>
    <tr>
      <td class="logo">{% if afm.logo %}<img src="{{ afm.logo }}" alt="AFMCO">{% endif %}</td>
      <td></td>
      <td>
        <table class="ids">
          <colgroup><col style="width:24mm"><col><col style="width:14mm"></colgroup>
          {%- if afm.vat %}
          {%- set _k = _('Tax Id', lang='ar') %}
          <tr><td class="k">{{ _k if _k != 'Tax Id' else '' }}</td><td class="num ctr"><b>{{ afm.vat }}</b></td><td class="k ltr" style="text-align:left;">VAT No.</td></tr>
          {%- endif %}
          {%- if afm.cr %}
          {%- set _k = _('Commercial Registration Number', lang='ar') %}
          <tr><td class="k">{{ _k if _k != 'Commercial Registration Number' else '' }}</td><td class="num ctr"><b>{{ afm.cr }}</b></td><td class="k ltr" style="text-align:left;">CR No.</td></tr>
          {%- endif %}
        </table>
      </td>
    </tr>
  </table>
  <table class="rule"><colgroup><col style="width:22%"><col></colgroup><tr><td class="thick"></td><td class="thin"></td></tr></table>
</div>
</div>

{%- set _pg = _('Page', lang='ar') -%}
<div id="footer-html">
<div class="afm afm-ftr" dir="rtl" lang="ar">
  <table>
    <colgroup><col><col style="width:40mm"><col style="width:34mm"></colgroup>
    <tr>
      <td><span class="co">{{ afm.name_ar }}</span>{% if afm.addr %} &nbsp;|&nbsp; {{ afm.addr }}{% endif %}<div class="ltr2">{{ afm.name_en }}{% if afm.phone %} &nbsp;|&nbsp; T {{ afm.phone }}{% endif %}{% if afm.web %} &nbsp;|&nbsp; {{ afm.web }}{% endif %}</div></td>
      <td class="num ctr">{{ doc.name }}</td>
      <td class="pg" style="text-align:left;">{% if _pg != 'Page' %}{{ _pg }}&nbsp; {% endif %}<span class="ltr">Page <span class="page"></span> / <span class="topage"></span></span></td>
    </tr>
  </table>
</div>
</div>

{%- macro s_money(v) -%}{{ frappe.utils.fmt_money((v or 0) | abs, 2) }}{%- endmacro -%}
{%- macro s_qty(v) -%}{%- set q = (v or 0) | abs -%}{{ frappe.utils.fmt_money(q, 0) if q == (q | int) else frappe.utils.fmt_money(q, 2) }}{%- endmacro -%}
{%- macro s_pct(v) -%}{{ '%g' | format(frappe.utils.flt(v or 0, 2)) }}%{%- endmacro -%}
{%- macro s_row(en, ar_key, value, value_cls='') -%}
<table class="sam-kv"><colgroup><col style="width:22%"><col><col style="width:22%"></colgroup>
<tr><td class="lb-en"><span class="en">{{ en }}</span></td><td class="v ctr {{ value_cls }}">{{ value }}</td><td class="lb-ar"><span class="ar">{{ _(ar_key, "ar", "Samsa Tax Invoice") }}</span></td></tr></table>
{%- endmacro -%}
{%- macro s_party(en_s, ar_s, v_s, en_b, ar_b, v_b, cls_s='', cls_b='', tcls='') -%}
<table class="sam-party {{ tcls }}"><colgroup><col style="width:12%"><col style="width:26%"><col style="width:12%"><col style="width:12%"><col style="width:26%"><col style="width:12%"></colgroup>
<tr><td class="lb-en"><span class="en">{{ en_s }}</span></td><td class="v ctr {{ cls_s }}">{{ v_s }}</td><td class="lb-ar"><span class="ar">{{ ar_s }}</span></td><td class="lb-en"><span class="en">{{ en_b }}</span></td><td class="v ctr {{ cls_b }}">{{ v_b }}</td><td class="lb-ar"><span class="ar">{{ ar_b }}</span></td></tr></table>
{%- endmacro -%}


{%- set s_details = get_phase_2_print_format_details(doc) if frappe.db.exists('Sales Invoice Additional Fields', {'sales_invoice': doc.name}) else none -%}
{%- set s_qr = ((s_details.siaf.qr_image_src if s_details and s_details.siaf else none) or doc.get('ksa_einv_qr')) -%}
{%- set s_buyer_cr = ((s_details.buyer_other_id if s_details else '') or doc.get('client_ccr_no') or '') -%}
{%- set s_cur = doc.currency or '' -%}

<div class="afm sam" dir="rtl" lang="ar">
  <table class="sam-title"><colgroup><col style="width:50%"><col style="width:50%"></colgroup>
    <tr><th class="t-en"><span class="ltr">Tax Invoice</span></th><th class="t-ar">{{ _("Tax Invoice", "ar", "Samsa Tax Invoice") }}</th></tr>
  </table>

  <table class="sam-top"><colgroup><col><col style="width:30mm"></colgroup>
    <tr>
      <td class="meta">
        {{ s_row('Invoice No.', 'Invoice Number', doc.name, 'b num') }}
        {{ s_row('Issue Date', 'Issue Date', frappe.utils.formatdate(doc.posting_date, 'yyyy-mm-dd'), 'num') }}
        {{ s_row('Supply Date', 'Supply Date', frappe.utils.formatdate(doc.posting_date, 'yyyy-mm-dd'), 'num') }}
        {{ s_row('P.O. No.', 'Purchase Order Number', doc.po_no or '', '') }}
        {{ s_row('P.O. Date', 'Purchase Order Date', frappe.utils.formatdate(doc.po_date, 'yyyy-mm-dd') if doc.po_date else '', 'num') }}
      </td>
      <td class="qr">{% if s_qr %}<img src="{{ s_qr }}" alt="ZATCA QR">{% endif %}</td>
    </tr>
  </table>

  <div class="sam-parties">
    {{ s_party('Seller', _("Supplier", "ar", "Samsa Tax Invoice"), '', 'Client', _("Buyer", "ar", "Samsa Tax Invoice"), '', '', '', 'hd') }}
    {{ s_party('Name', _("Name", "ar", "Samsa Tax Invoice"), afm.name_ar, 'Name', _("Name", "ar", "Samsa Tax Invoice"), doc.customer_name, 'b wrap', 'b wrap') }}
    {{ s_party('Address', _("Address", "ar", "Samsa Tax Invoice"), doc.company_address_display or '', 'Address', _("Address", "ar", "Samsa Tax Invoice"), doc.address_display or '', 'wrap', 'wrap') }}
    {{ s_party('VAT No.', _("Tax Id", "ar"), doc.company_tax_id or '', 'VAT No.', _("Tax Id", "ar"), doc.tax_id or '', 'num', 'num') }}
    {{ s_party('Seller CR', _("Commercial Registration", "ar", "Samsa Tax Invoice"), afm.cr, 'Client CR', _("Commercial Registration", "ar", "Samsa Tax Invoice"), s_buyer_cr, 'num', 'num') }}
  </div>

  <table class="sam-items">
    <colgroup><col><col style="width:5%"><col style="width:6.5%"><col style="width:10%"><col style="width:6%"><col style="width:13.5%"><col style="width:9%"><col style="width:9%"><col style="width:17.5%"></colgroup>
    <thead>
      <tr>
        <th class="ctr"><span class="en">Product</span><span class="ar">{{ _("Products", "ar", "Samsa Tax Invoice") }}</span><span class="en cur">&nbsp;</span></th>
        <th><span class="en">Qty</span><span class="ar">{{ _("Quantity", "ar", "Samsa Tax Invoice") }}</span><span class="en cur">&nbsp;</span></th>
        <th><span class="en">Rate</span><span class="ar">{{ _("Rate", "ar", "Samsa Tax Invoice") }}</span><span class="en cur">{{ s_cur }}</span></th>
        <th><span class="en">Value</span><span class="ar">{{ _("Value", "ar", "Samsa Tax Invoice") }}</span><span class="en cur">{{ s_cur }}</span></th>
        <th><span class="en">Discount</span><span class="ar">{{ _("Discount", "ar", "Samsa Tax Invoice") }}</span><span class="en cur">{{ s_cur }}</span></th>
        <th><span class="en">Taxable Amount</span><span class="ar">{{ _("Taxable Amount", "ar", "Samsa Tax Invoice") }}</span><span class="en cur">{{ s_cur }}</span></th>
        <th><span class="en">Tax %</span><span class="ar">{{ _("Tax Rate", "ar", "Samsa Tax Invoice") }}</span><span class="en cur">&nbsp;</span></th>
        <th><span class="en">Tax Amount</span><span class="ar">{{ _("Tax Amount", "ar", "Samsa Tax Invoice") }}</span><span class="en cur">{{ s_cur }}</span></th>
        <th><span class="en">Total inclusive of VAT</span><span class="ar">{{ _("Total inclusive of VAT", "ar", "Samsa Tax Invoice") }}</span><span class="en cur">{{ s_cur }}</span></th>
      </tr>
    </thead>
    <tbody>
      {%- for item in doc.items %}
      {%- set s_desc = ((item.description or '') | replace('&nbsp;', ' ') | striptags).split() | join(' ') or item.item_name or '' -%}
      {%- set s_ar = (s_desc | select('ge', '؀') | select('le', 'ۿ') | list | length) > 0 -%}
      <tr>
        <td class="ctr desc{{ '' if s_ar else ' ltr' }}">{{ s_desc }}</td>
        <td class="num">{{ s_qty(item.qty) }}</td>
        <td class="num">{{ s_money(item.rate) }}</td>
        <td class="num">{{ s_money(item.amount) }}</td>
        <td class="num">{{ s_money((item.amount or 0) - (item.net_amount or 0)) }}</td>
        <td class="num">{{ s_money(item.net_amount) }}</td>
        <td class="num">{{ s_pct(item.get('tax_rate') or 15) }}</td>
        <td class="num">{{ s_money(item.get('tax_amount')) }}</td>
        <td class="num">{{ s_money(item.get('total_amount')) }}</td>
      </tr>
      {%- endfor %}
    </tbody>
  </table>

  <table class="sam-close"><tr><td>
  <table class="sam-band"><colgroup><col style="width:50%"><col style="width:50%"></colgroup>
    <tr><td class="lb-en"><span class="en">Total Amount ({{ s_cur }})</span></td><td class="lb-ar"><span class="ar">{{ _("Total Amounts", "ar", "Samsa Tax Invoice") }}</span></td></tr>
  </table>
  <table class="sam-tot"><colgroup><col style="width:40%"><col style="width:40%"><col style="width:20%"></colgroup>
    <tr><td class="lb-en"><span class="en">Total (Excluding VAT)</span></td><td class="lb-ar"><span class="ar">{{ _("Total (Excluding VAT)", "ar", "Samsa Tax Invoice") }}</span></td><td class="num">{{ s_money(doc.total) }}</td></tr>
